import pypdf
reader = pypdf.PdfReader('C:/Users/wakil/Downloads/CAS_PCBA_Engineer_interior_KDP.pdf')
def dump_outline(items, depth=0):
    for item in items:
        if isinstance(item, list):
            dump_outline(item, depth+1)
        else:
            title = getattr(item, 'title', str(item))
            page = reader.get_destination_page_number(item) if hasattr(item, 'page') else '?'
            print('  '*depth + f'{title} (p. {page})')

dump_outline(reader.outline[:15])
""}

